bootforge/http-rest/http/methods-and-sem.solution:
export function lintRequest(req) {
  const warnings = [];
  const upper = req.method.toUpperCase();
  const known = ['GET', 'HEAD', 'OPTIONS', 'POST', 'PUT', 'PATCH', 'DELETE'];
  if (req.method !== upper) warnings.push('method should be uppercase');
  if (!known.includes(upper)) warnings.push('unknown method');
  if (['GET', 'HEAD', 'OPTIONS'].includes(upper) && req.body !== null) {
    warnings.push('safe requests should not have a body');
  }
  if (['POST', 'PUT', 'PATCH'].includes(upper) && req.body === null) {
    warnings.push('this method usually carries a body');
  }
  if (!req.path.startsWith('/')) warnings.push('path should start with /');
  return warnings;
}

