bootforge/http-rest/http/status-codes/st.solution:
export function summarizeStatuses(codes) {
  if (codes.length === 0) return { total: 0, families: {}, errorRate: 0 };
  const families = {};
  let errors = 0;
  for (const code of codes) {
    const fam = Math.floor(code / 100) + 'xx';
    families[fam] = (families[fam] ?? 0) + 1;
    if (code >= 400 && code <= 599) errors++;
  }
  const errorRate = Math.round((errors / codes.length) * 100) / 100;
  return { total: codes.length, families, errorRate };
}

