bootforge/http-rest/http/headers-and-con.solution:
export function negotiate(acceptValue, available) {
  if (acceptValue === null || acceptValue === undefined || acceptValue === '') {
    return available[0] ?? null;
  }
  const wanted = acceptValue
    .split(',')
    .map((part) => part.trim().split(';')[0].trim())
    .filter((t) => t !== '');
  for (const want of wanted) {
    if (want === '*/*') return available[0] ?? null;
    if (want.endsWith('/*')) {
      const prefix = want.slice(0, want.indexOf('/'));
      const hit = available.find((a) => a.startsWith(prefix + '/'));
      if (hit) return hit;
    } else if (available.includes(want)) {
      return want;
    }
  }
  return null;
}

