  if (!path.startsWith('/')) return false;
  const segments = path.split('/').filter((s) => s !== '');
  const verbs = ['get', 'create', 'update', 'delete', 'new', 'edit'];
  for (let i = 0; i < segments.length; i++) {
    if (verbs.includes(segments[i])) return false;
    if (i % 2 === 0 && !/^[a-z]+$/.test(segments[i])) return false;
  }
  return true;
}

