  // your code here
}

bootforge/http-rest/rest-and-urls/reques.solution:
export function validateBody(body, specs) {
  const errors = [];
  for (const [field, spec] of Object.entries(specs)) {
    const value = body[field];
    if (value === undefined) {
      if (spec.required) errors.push({ field, message: `${field} is required` });
      continue;
    }
    if (spec.type !== undefined && typeof value !== spec.type) {
      errors.push({ field, message: `${field} must be a ${spec.type}` });
      continue;
    }
    if (
      spec.maxLength !== undefined &&
      typeof value === 'string' &&
      value.length > spec.maxLength
    ) {
      errors.push({ field, message: `${field} must be at most ${spec.maxLength} characters` });
    }
  }
  return errors;
}

