export function processRegistration(body) {
  const errors = [];
  if (body.name === undefined) {
    errors.push('name is required');
  } else if (typeof body.name !== 'string') {
    errors.push('name must be a string');
  } else if (body.name.length > 50) {
    errors.push('name must be at most 50 characters');
  }
  if (body.email === undefined) {
    errors.push('email is required');
  } else if (typeof body.email !== 'string') {
    errors.push('email must be a string');
  } else if (!body.email.includes('@')) {
    errors.push('email must contain @');
  }
  if (body.role !== undefined && !['user', 'admin'].includes(body.role)) {
    errors.push('role must be one of: user, admin');
  }
  if (errors.length > 0) return { ok: false, errors };
  return {
    ok: true,
    user: {
      name: body.name.trim(),
      email: body.email.trim(),
      role: body.role ?? 'user',
    },
  };
}
